/**
 * @name Path traversal in file operations
 * @description User-controlled data flowing to file operations may allow path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/boto3-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters that could be user-controlled
    source instanceof DataFlow::ParameterNode or
    // Attribute access that might come from external input
    exists(DataFlow::AttrRead attr |
      source = attr and
      attr.getAttributeName() in ["key", "filename", "path", "name", "Key", "Bucket"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File system access operations
    exists(FileSystemAccess fsa |
      sink = fsa.getAPathArgument()
    ) or
    // Direct file operations
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["open", "read", "write"] and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled input"

/**
 * @name Command injection in boto3
 * @description Detects potential command injection vulnerabilities where user input flows to system command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/boto3-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.dataflow.new.RemoteFlowSources

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from $@.", source.getNode(), "user-controlled input"

/**
 * @name Insecure deserialization in boto3
 * @description Detects potential insecure deserialization vulnerabilities using pickle
 * @kind path-problem
 * @problem.severity error
 * @id py/boto3-insecure-deserialization
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module InsecureDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("sys").getMember("stdin").getMember("read").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads", "Unpickler"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module InsecureDeserializationFlow = TaintTracking::Global<InsecureDeserializationConfig>;
import InsecureDeserializationFlow::PathGraph

from InsecureDeserializationFlow::PathNode source, InsecureDeserializationFlow::PathNode sink
where InsecureDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential insecure deserialization from $@.", source.getNode(), "user-controlled input"

/**
 * @name SQL injection in boto3
 * @description Detects potential SQL injection vulnerabilities
 * @kind path-problem
 * @problem.severity error
 * @id py/boto3-sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.dataflow.new.RemoteFlowSources

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SQL injection from $@.", source.getNode(), "user-controlled input"
